/** Slug used to load public/geo/districts/<slug>.json for a state name. */
export const STATE_SLUG_BY_NAME = Object.fromEntries(
  INDIA_STATES.map((state) => [state.name, state.slug]),
)

export const STATE_NAMES = INDIA_STATES.map((state) => state.name)

export function districtsOf(stateName) {
  return INDIA_STATES.find((state) => state.name === stateName)?.districts ?? []
}
